-- PHASE 2B.2 DESIGN DRAFT. NOT A DEPLOYABLE MIGRATION. Do not place under
-- supabase/migrations or apply to a Supabase project.
--
-- Adds append-only numbered correction-attempt records to the reviewed 001-006
-- baseline, which modelled a correction as exactly one immutable
-- match_corrections.draft_revision_id with no attempt sequence.
--
-- Contract implemented here (Phase 2A.5 section 2):
--   * every correction has immutable, numbered attempts starting at 1;
--   * a rejected attempt stays historical and is never rewritten;
--   * only the latest attempt of a correction may be approved or source a result;
--   * a new attempt copies the previous attempt's snapshot and links it as the
--     prior attempt, so lineage and audit history are preserved;
--   * a new correction case is never opened for a retry while a case is open.
--
-- Client access stays fail-closed: SELECT for leaders only on the attempt rows,
-- no client DML, and no EXECUTE grant on the mutation function.

create table public.match_correction_attempts (
  id uuid primary key default gen_random_uuid(),
  league_id uuid not null,
  match_id uuid not null,
  correction_id uuid not null,
  attempt_no integer not null check (attempt_no > 0),
  draft_revision_id uuid not null,
  prior_attempt_id uuid,
  created_by uuid not null,
  created_at timestamptz not null default now(),
  unique (league_id, id),
  unique (league_id, match_id, id),
  unique (correction_id, attempt_no),
  unique (draft_revision_id),
  unique (prior_attempt_id),
  check ((attempt_no = 1 and prior_attempt_id is null) or (attempt_no > 1 and prior_attempt_id is not null)),
  foreign key (league_id, correction_id) references public.match_corrections (league_id, id) on delete restrict,
  foreign key (league_id, match_id, draft_revision_id) references public.match_revisions (league_id, match_id, id) on delete restrict,
  foreign key (league_id, match_id, prior_attempt_id) references public.match_correction_attempts (league_id, match_id, id) on delete restrict,
  foreign key (league_id, created_by) references public.league_members (league_id, user_id) on delete restrict
);
create index correction_attempts_match_idx on public.match_correction_attempts (league_id, match_id, attempt_no desc);

alter table public.match_correction_attempts enable row level security;
revoke all on public.match_correction_attempts from public, anon, authenticated;
grant select on public.match_correction_attempts to authenticated;
create policy correction_attempt_leader on public.match_correction_attempts
  for select to authenticated using (ff_private.is_leader(league_id));

-- Attempts are append-only facts. Rows are inserted only by the reviewed
-- functions below or by the automatic first-attempt trigger on correction insert.
create trigger correction_attempts_append_only
  before update or delete on public.match_correction_attempts
  for each row execute function ff_private.append_only();

-- The latest attempt of one correction, or null. Attempt numbers are dense and
-- monotonic per correction, so the maximum is the latest.
create function ff_private.latest_correction_attempt(p_league uuid, p_correction uuid) returns uuid
language sql stable security definer set search_path=pg_catalog,ff_private as $$
  select a.id from public.match_correction_attempts a
  where a.league_id = p_league and a.correction_id = p_correction
  order by a.attempt_no desc limit 1
$$;

-- The latest attempt across the whole match: the single eligible source revision
-- once a correction is open. Ordering is by the attempt's revision version, which
-- is unique and monotonic per match, so it never depends on timestamp resolution.
-- A correction attempt always has a higher version than every revision that
-- preceded it, including all pre-correction approvals.
create function ff_private.latest_match_correction_attempt(p_league uuid, p_match uuid) returns uuid
language sql stable security definer set search_path=pg_catalog,ff_private as $$
  select a.id
  from public.match_correction_attempts a
  join public.match_revisions v on v.league_id = a.league_id and v.id = a.draft_revision_id
  where a.league_id = p_league and a.match_id = p_match
  order by v.version desc limit 1
$$;

-- Opening a correction creates attempt 1 atomically. Runs after 004's
-- after_correction so the supersession of the old result is already recorded.
create function ff_private.record_first_correction_attempt() returns trigger
language plpgsql security definer set search_path=pg_catalog,ff_private as $$
begin
  insert into public.match_correction_attempts(league_id, match_id, correction_id, attempt_no, draft_revision_id, created_by)
  values (new.league_id, new.match_id, new.id, 1, new.draft_revision_id, new.actor_id);
  return new;
end $$;
create trigger zz_after_correction_attempt after insert on public.match_corrections
  for each row execute function ff_private.record_first_correction_attempt();

-- A correction whose case is still open (no current official result) may not be
-- followed by a second case for the same match: retries use numbered attempts.
create function ff_private.guard_single_open_correction() returns trigger
language plpgsql security definer set search_path=pg_catalog,ff_private as $$
begin
  -- A prior case is resolved once a later official result exists for the match.
  -- official_match_results carries no timestamp, so the later superseding result
  -- is identified through the match revision it points at.
  if exists (
    select 1 from public.match_corrections c
    join public.match_revisions cv on cv.league_id = c.league_id and cv.id = c.draft_revision_id
    where c.league_id = new.league_id and c.match_id = new.match_id and c.id <> new.id
      and not exists (
        select 1 from public.official_match_results o
        join public.match_revisions ov on ov.league_id = o.league_id and ov.id = o.revision_id
        where o.league_id = c.league_id and o.match_id = c.match_id and ov.version > cv.version
      )
  ) then
    raise exception 'an unresolved correction case already exists for this match' using errcode='23514';
  end if;
  return new;
end $$;
create trigger zzz_guard_single_open_correction after insert on public.match_corrections
  for each row execute function ff_private.guard_single_open_correction();

-- Only the latest attempt of a correction may be approved. An earlier attempt's
-- approval stays historical but is never a valid result source. 005's
-- require_current_lineup already rejects a stale lineup, but it derives the
-- requirement from match_corrections.draft_revision_id; this check is bound to
-- the attempt sequence itself and does not depend on that column.
create function ff_private.guard_correction_attempt_approval() returns trigger
language plpgsql security definer set search_path=pg_catalog,ff_private as $$
declare attempt public.match_correction_attempts%rowtype;
begin
  if new.kind <> 'lineup' then return new; end if;
  select * into attempt from public.match_correction_attempts a
  where a.league_id = new.league_id and a.draft_revision_id = new.revision_id;
  if not found then return new; end if;
  if exists (
    select 1 from public.match_correction_attempts a
    where a.league_id = attempt.league_id and a.correction_id = attempt.correction_id
      and a.attempt_no > attempt.attempt_no
  ) then
    raise exception 'only the latest correction attempt may be approved' using errcode='23514';
  end if;
  return new;
end $$;
create trigger zzz_guard_correction_attempt_approval before insert on public.match_approvals
  for each row execute function ff_private.guard_correction_attempt_approval();

-- Attempt-aware replacement of 004's require_latest_corrected_lineup. The
-- required revision is now the latest attempt's draft, not
-- match_corrections.draft_revision_id (which is always attempt 1).
create or replace function ff_private.require_latest_corrected_lineup(p_league uuid, p_match uuid, p_revision uuid) returns void
language plpgsql security definer set search_path=pg_catalog,ff_private as $$
declare required_revision uuid;
begin
  select a.draft_revision_id into required_revision
  from public.match_correction_attempts a
  join public.match_revisions v on v.league_id = a.league_id and v.id = a.draft_revision_id
  where a.league_id = p_league and a.match_id = p_match
  order by v.version desc limit 1;
  if required_revision is not null and required_revision <> p_revision then
    raise exception 'latest corrected lineup requires reapproval' using errcode='23514';
  end if;
end $$;

-- Attempt-aware replacement of 005's guard_submission_generation. The correction
-- draft a new lineup submission must match is the latest attempt's draft.
create or replace function ff_private.guard_submission_generation() returns trigger
language plpgsql security definer set search_path=pg_catalog,ff_private as $$
declare corrected uuid; source_revision uuid;
begin
  perform ff_private.require_read_committed();
  if new.kind = 'lineup' then
    if exists (select 1 from public.official_match_results o
               where o.league_id = new.league_id and o.match_id = new.match_id and o.is_current) then
      raise exception 'official result requires correction before a new lineup' using errcode='23514';
    end if;
    select a.draft_revision_id into corrected
    from public.match_correction_attempts a
    join public.match_revisions v on v.league_id = a.league_id and v.id = a.draft_revision_id
    where a.league_id = new.league_id and a.match_id = new.match_id
    order by v.version desc limit 1;
    if corrected is not null and corrected <> new.revision_id then
      raise exception 'stale lineup submission after correction' using errcode='23514';
    end if;
  else
    select a.revision_id into source_revision from public.match_approvals a
    where a.league_id = new.league_id and a.match_id = new.match_id and a.id = new.approved_lineup_approval_id
      and a.kind = 'lineup' and a.decision = 'approved';
    perform ff_private.require_current_lineup(new.league_id, new.match_id, source_revision);
  end if;
  return new;
end $$;

-- Attempt-aware replacement of 005's validate_approval. 005 derives the required
-- correction revision from match_corrections.draft_revision_id, which is always
-- attempt 1, so approving attempt 2 or later would be rejected as "stale". This
-- version requires the latest attempt's revision instead, and keeps every other
-- check from 005 unchanged.
create or replace function ff_private.validate_approval() returns trigger
language plpgsql security definer set search_path=pg_catalog,ff_private as $$
declare sub public.match_submissions%rowtype; source_revision uuid; corrected uuid;
begin
  perform ff_private.require_read_committed();
  perform 1 from public.real_matches where league_id = new.league_id and id = new.match_id for update;
  if not found then raise exception 'match not found' using errcode='23514'; end if;
  perform ff_private.require_leader(new.league_id);
  if new.reviewed_by is distinct from auth.uid() then raise exception 'invalid reviewer' using errcode='42501'; end if;
  select * into sub from public.match_submissions
  where league_id = new.league_id and id = new.submission_id and match_id = new.match_id
    and revision_id = new.revision_id and kind = new.kind;
  if not found or not exists (select 1 from public.match_revisions
      where league_id = new.league_id and match_id = new.match_id and id = new.revision_id and state = 'submitted') then
    raise exception 'submission is not awaiting review' using errcode='23514'; end if;
  if exists (select 1 from public.match_submissions newer
    join public.match_revisions nr on nr.league_id = newer.league_id and nr.match_id = newer.match_id and nr.id = newer.revision_id
    join public.match_revisions cur on cur.league_id = sub.league_id and cur.match_id = sub.match_id and cur.id = sub.revision_id
    where newer.league_id = sub.league_id and newer.match_id = sub.match_id and newer.kind = sub.kind and nr.version > cur.version) then
    raise exception 'submission superseded by newer revision' using errcode='23514'; end if;
  if sub.submitted_by = auth.uid() then raise exception 'self approval is forbidden' using errcode='42501'; end if;
  if new.decision = 'rejected' and (new.reason is null or length(btrim(new.reason)) = 0) then
    raise exception 'rejection needs a reason' using errcode='23514'; end if;
  -- Latest correction attempt, ordered by revision version (unique per match).
  select a.draft_revision_id into corrected
  from public.match_correction_attempts a
  join public.match_revisions r on r.league_id = a.league_id and r.id = a.draft_revision_id
  where a.league_id = new.league_id and a.match_id = new.match_id
  order by r.version desc limit 1;
  if new.kind = 'lineup' and exists (select 1 from public.official_match_results o
      where o.league_id = new.league_id and o.match_id = new.match_id and o.is_current) then
    raise exception 'official result requires correction before a new lineup' using errcode='23514'; end if;
  if new.kind = 'lineup' and corrected is not null and new.revision_id <> corrected then
    raise exception 'stale lineup submission after correction' using errcode='23514'; end if;
  if new.kind = 'result' then
    select a.revision_id into source_revision from public.match_approvals a
    join public.match_revisions r on r.league_id = a.league_id and r.match_id = a.match_id and r.id = a.revision_id
    where a.league_id = sub.league_id and a.match_id = sub.match_id and a.id = sub.approved_lineup_approval_id
      and a.kind = 'lineup' and a.decision = 'approved' and r.state = 'approved';
    if source_revision is null then raise exception 'approved lineup lineage required' using errcode='23514'; end if;
    perform ff_private.require_current_lineup(new.league_id, new.match_id, source_revision);
  end if;
  return new;
end $$;

-- Start the next numbered attempt from the rejected snapshot of the latest
-- attempt, inside the same still-open correction case. Leader-only, and only
-- after a recorded rejection: a pending or approved attempt cannot be forked.
create function ff_private.open_correction_attempt(p_league uuid, p_correction uuid) returns uuid
language plpgsql security definer set search_path=pg_catalog,ff_private as $$
declare c public.match_corrections%rowtype; prev public.match_correction_attempts%rowtype;
        next_no integer; next_rev uuid; next_ver integer; line record; next_line uuid;
begin
  perform ff_private.require_read_committed();
  select * into c from public.match_corrections where league_id = p_league and id = p_correction;
  if not found then raise exception 'correction not found' using errcode='23514'; end if;
  perform 1 from public.real_matches where league_id = p_league and id = c.match_id for update;
  perform ff_private.require_leader(p_league);
  if exists (select 1 from public.official_match_results o
             where o.league_id = p_league and o.match_id = c.match_id and o.is_current) then
    raise exception 'correction case is already resolved by a current official result' using errcode='23514';
  end if;
  select * into prev from public.match_correction_attempts a
  where a.league_id = p_league and a.correction_id = p_correction
  order by a.attempt_no desc limit 1;
  if not found then raise exception 'correction has no attempt' using errcode='23514'; end if;
  -- The prior attempt must be a rejected lineup with no pending or approved result.
  if not exists (
    select 1 from public.match_submissions s
    join public.match_approvals a on a.league_id = s.league_id and a.submission_id = s.id
    where s.league_id = p_league and s.match_id = c.match_id and s.revision_id = prev.draft_revision_id
      and s.kind = 'lineup' and a.kind = 'lineup' and a.decision = 'rejected'
  ) then
    raise exception 'a new attempt requires the previous attempt to be rejected' using errcode='23514';
  end if;
  if exists (select 1 from public.match_revisions v
             where v.league_id = p_league and v.id = prev.draft_revision_id and v.state <> 'rejected') then
    raise exception 'previous attempt revision is not final' using errcode='23514';
  end if;
  next_no := prev.attempt_no + 1;
  select coalesce(max(version), 0) + 1 into next_ver from public.match_revisions
  where league_id = p_league and match_id = c.match_id;
  insert into public.match_revisions(league_id, match_id, version, match_snapshot, corrects_revision_id)
  select p_league, c.match_id, next_ver, match_snapshot, corrects_revision_id
  from public.match_revisions where league_id = p_league and id = prev.draft_revision_id
  returning id into next_rev;
  for line in select * from public.real_match_lineups where league_id = p_league and revision_id = prev.draft_revision_id loop
    insert into public.real_match_lineups(league_id, match_id, revision_id, team_id)
    values (p_league, c.match_id, next_rev, line.team_id) returning id into next_line;
    insert into public.real_match_lineup_players(league_id, revision_id, lineup_id, player_id, selection, actual_position, eligibility_kind, eligibility_evidence)
    select league_id, next_rev, next_line, player_id, selection, actual_position, eligibility_kind, eligibility_evidence
    from public.real_match_lineup_players where league_id = p_league and lineup_id = line.id;
  end loop;
  insert into public.match_correction_attempts(league_id, match_id, correction_id, attempt_no, draft_revision_id, prior_attempt_id, created_by)
  values (p_league, c.match_id, p_correction, next_no, next_rev, prev.id, auth.uid());
  insert into public.audit_logs(league_id, actor_id, action, entity_type, entity_id, after_data)
  values (p_league, auth.uid(), 'open_correction_attempt', 'match', c.match_id,
          jsonb_build_object('correction', p_correction, 'attempt_no', next_no,
                             'draft_revision', next_rev, 'prior_attempt', prev.id));
  return next_rev;
end $$;

